INSERT INTO concepts (id, subject_id, name) VALUES ('00000000-0000-0000-0000-000000000103', '00000000-0000-0000-0000-0000000000a1', 'Poisson counts and waiting times') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020301', '00000000-0000-0000-0000-000000000103', 'If customers arrive as a Poisson process with rate 20 per hour and each buys with probability 0.30, the number of sales N(t) is a Poisson process with rate 20·0.3 = 6, so E[N(8)] = 48 over an eight-hour day.', '00000000-0000-0000-0000-0000000000b1', 'p.5, Q1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020302', '00000000-0000-0000-0000-000000000103', 'With N(t) Poisson of rate 6 per hour, P(N(1) >= 10) = 1 - sum_{n=0}^{9} e^{-6} 6^n / n! = 1 - 0.9161 = 0.0839.', '00000000-0000-0000-0000-0000000000b1', 'p.5, Q1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020303', '00000000-0000-0000-0000-000000000103', 'The time Z1 until the first sale is exponentially distributed with mean 1/6 hour, so for a 10 a.m. opening the expected time of the first sale is 10:10 a.m.', '00000000-0000-0000-0000-0000000000b1', 'p.5, Q1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020304', '00000000-0000-0000-0000-000000000103', 'Given N(1) = 6, P(N(2)-N(1) <= 2 | N(1) = 6) = P(N(1) <= 2) = sum_{n=0}^{2} e^{-6} 6^n / n! = 0.06197.', '00000000-0000-0000-0000-0000000000b1', 'p.5, Q1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, subject_id, name) VALUES ('00000000-0000-0000-0000-000000000104', '00000000-0000-0000-0000-0000000000a1', 'Generators and transition matrices') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020401', '00000000-0000-0000-0000-000000000104', 'For the generator G = [[-1, 1], [4, -4]], the transition matrix is P(t) = e^{tG}.', '00000000-0000-0000-0000-0000000000b1', 'p.3, Ex 3.5', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020402', '00000000-0000-0000-0000-000000000104', 'For that G, P(t) has rows (4/5 + (1/5)e^{-5t}, 1/5 - (1/5)e^{-5t}) and (4/5 - (4/5)e^{-5t}, 1/5 + (4/5)e^{-5t}).', '00000000-0000-0000-0000-0000000000b1', 'p.3, Ex 3.5', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020403', '00000000-0000-0000-0000-000000000104', 'In the permanent disability model with states healthy (0), permanently disabled (1) and death (2), transition probabilities are estimated by solving Kolmogorov''s forward equations numerically with Euler''s forward method and step h = 0.1.', '00000000-0000-0000-0000-0000000000b1', 'p.7, Q3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020404', '00000000-0000-0000-0000-000000000104', 'In the first Euler step p00(0.1) = 1 - 0.006 = 0.994 and p01(0.1) = 0.1·0.05 = 0.005; after the second step p01(0.2) = 0.00992 and p00(0.2) = 0.994^2 = 0.988036.', '00000000-0000-0000-0000-0000000000b1', 'p.7, Q3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, subject_id, name) VALUES ('00000000-0000-0000-0000-000000000105', '00000000-0000-0000-0000-0000000000a1', 'Stationary distribution from balance equations') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020501', '00000000-0000-0000-0000-000000000105', 'The stationary distribution π of a finite-state continuous-time Markov chain with generator G solves the balance equation πG = 0 together with a normalisation condition.', '00000000-0000-0000-0000-0000000000b1', 'p.3, Ex 3.8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020502', '00000000-0000-0000-0000-000000000105', 'For the generator with rows (-3, 1, 1, 1), (0, -3, 2, 1), (1, 2, -4, 1), (0, 0, 1, -1), the stationary distribution is π = (3, 7, 9, 19)/38.', '00000000-0000-0000-0000-0000000000b1', 'p.3, Ex 3.8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020503', '00000000-0000-0000-0000-000000000105', 'For the generator with rows (-2, 1, 1, 0), (0, -1, 1, 0), (1, 1, -3, 1), (0, 0, 1, -1), the stationary distribution is π = (1, 3, 2, 2)/8.', '00000000-0000-0000-0000-0000000000b1', 'p.8, Q4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020504', '00000000-0000-0000-0000-000000000105', 'In the taxi chain (state 0 waiting at location 1, state 1 waiting at location 2, state 2 driving from 1 to 2, state 3 driving from 2 to 1), the chain is irreducible with a finite state space, so the stationary distribution exists and is unique, and lim_{t->inf} p_{i0}(t) = π0 = 1/6.2 = 0.16129.', '00000000-0000-0000-0000-0000000000b1', 'p.9, Q5', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020505', '00000000-0000-0000-0000-000000000105', 'In the taxi chain, a mean waiting time of 5 minutes gives rate 0.2, a mean drive of 10 minutes from location 1 to 2 gives rate 0.1, and a mean drive of 11 minutes from location 2 to 1 gives rate 1/11.', '00000000-0000-0000-0000-0000000000b1', 'p.9, Q5', false) ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, subject_id, name) VALUES ('00000000-0000-0000-0000-000000000106', '00000000-0000-0000-0000-0000000000a1', 'Sojourn and hitting times') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020601', '00000000-0000-0000-0000-000000000106', 'In the chain of Ex 3.8 the sojourn time U1 of state 1 is Exp(3), so given X(0) = 1 the expected time until the first change of state is E[U1] = 1/3.', '00000000-0000-0000-0000-0000000000b1', 'p.3, Ex 3.8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020602', '00000000-0000-0000-0000-000000000106', 'In the chain of Ex 3.8, (-G_{-4})^{-1} 1 = (1, 1, 1)^T, so starting in state 1 the expected time until the chain is in state 4 is 1.', '00000000-0000-0000-0000-0000000000b1', 'p.3, Ex 3.8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020603', '00000000-0000-0000-0000-000000000106', 'In the chain of Q4 the sojourn time U1 of state 1 is Exp(2), so given X(0) = 1 the expected time until the first change of state is E[U1] = 1/2.', '00000000-0000-0000-0000-0000000000b1', 'p.8, Q4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020604', '00000000-0000-0000-0000-000000000106', 'In the chain of Q4, (-G_{-4})^{-1} 1 = (4, 4, 3)^T, so starting in state 1 the expected time until the chain is in state 4 is 4.', '00000000-0000-0000-0000-0000000000b1', 'p.8, Q4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, subject_id, name) VALUES ('00000000-0000-0000-0000-000000000107', '00000000-0000-0000-0000-0000000000a1', 'Birth-death recurrence criteria') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020701', '00000000-0000-0000-0000-000000000107', 'A birth-death process with birth rates λ_n (n = 0, 1, 2, ...) and death rates β_n (n = 1, 2, 3, ...) is transient if and only if the sum over n >= 1 of β_n···β_2β_1 / (λ_n···λ_2λ_1) is finite.', '00000000-0000-0000-0000-0000000000b1', 'p.1, Ex 3.11', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020702', '00000000-0000-0000-0000-000000000107', 'A birth-death process has a stationary distribution, equivalently is positive recurrent, if and only if the sum over n >= 1 of λ_{n-1}···λ_1λ_0 / (β_n···β_2β_1) is finite (Example 2.4 in lecture note 3).', '00000000-0000-0000-0000-0000000000b1', 'p.3, Ex 3.11', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020703', '00000000-0000-0000-0000-000000000107', 'For λ_n = 1 + 1/(n+1) = (n+2)/(n+1) and β_n = 1, both sums diverge (each equals ∞), so the process is null recurrent.', '00000000-0000-0000-0000-0000000000b1', 'p.4, Ex 3.11 (cont.)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020704', '00000000-0000-0000-0000-000000000107', 'For λ_n = 1 - 1/(n+2) = (n+1)/(n+2) and β_n = 1, both sums diverge (each equals ∞), so the process is null recurrent.', '00000000-0000-0000-0000-0000000000b1', 'p.4, Ex 3.11 (cont.)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020705', '00000000-0000-0000-0000-000000000107', 'In Ex 3.14 the sum of λ_{n-1}···λ_0 / (β_n···β_1) equals the sum of 1/n!, which is e - 1 < ∞, so the process is positive recurrent with π0 = 1/e and π_n = (1/n!)(1/e) for n = 1, 2, 3, ...', '00000000-0000-0000-0000-0000000000b1', 'p.4, Ex 3.14', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO concepts (id, subject_id, name) VALUES ('00000000-0000-0000-0000-000000000108', '00000000-0000-0000-0000-0000000000a1', 'Long-run behaviour of birth-death queues') ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020801', '00000000-0000-0000-0000-000000000108', 'For the birth-death process of Q7 (λ_n = n+1 for n = 0, 1, 2 and λ_n = n for n >= 3, with β_n = 2n), adding the earlier balance equations gives -(n+1)π_{n+1} + 2(n+2)π_{n+2} = 0, so π_{n+2} = (n+1)/(2(n+2)) π_{n+1}.', '00000000-0000-0000-0000-0000000000b1', 'p.11, Q7', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020802', '00000000-0000-0000-0000-000000000108', 'In Q7, π0 = 0.51166 and the long-run proportion of time that the population is at least 3 is 1 - π0 - π1 - π2 = 0.1046.', '00000000-0000-0000-0000-0000000000b1', 'p.12, Q7 (cont.)', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020803', '00000000-0000-0000-0000-000000000108', 'In the one-barber shop with room for two customers, arrivals at rate 3 per hour and service mean 0.25 hours, the chain has states {0, 1, 2} with q10 = q21 = 4, and its stationary distribution is π = (16, 12, 9)/37.', '00000000-0000-0000-0000-0000000000b1', 'p.13, Q8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020804', '00000000-0000-0000-0000-000000000108', 'In the barbershop chain, the average number of customers in the shop in the long run is π1 + 2π2 = 30/37, and the proportion of potential customers who enter the shop is the fraction of time the shop has 0 or 1 customers, π0 + π1 = 28/37.', '00000000-0000-0000-0000-0000000000b1', 'p.13, Q8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO claims (id, concept_id, text, source_id, locator, required) VALUES ('00000000-0000-0000-0000-000000020805', '00000000-0000-0000-0000-000000000108', 'If the barber works twice as fast, the barbershop stationary distribution is π = (64, 24, 9)/97, the entering proportion becomes 88/97, and business grows by (88/97)/(28/37) - 1 = 19.88%.', '00000000-0000-0000-0000-0000000000b1', 'p.13, Q8', true) ON CONFLICT (id) DO NOTHING;
